  "Area Manager for the Agri department at IGO Group, managing regional agri operations end-to-end — from field team coordination to on-ground project execution — within his assigned area. Works closely with the core Agri Operations team to maintain consistency across IGO's farm sites.": "IGO Group के एग्री विभाग में क्षेत्र प्रबंधक, जो अपने सौंपे गए क्षेत्र में फ़ील्ड टीम समन्वय से लेकर ज़मीनी परियोजना क्रियान्वयन तक क्षेत्रीय एग्री संचालन को शुरू से अंत तक संभालते हैं। IGO के फ़ार्म साइटों में एकरूपता बनाए रखने के लिए कोर एग्री ऑपरेशंस टीम के साथ मिलकर काम करते हैं।",
  "Area Manager for the Agri department at IGO Group, overseeing day-to-day farm operations and field execution within his assigned region. Coordinates with local field teams and farmers to keep agri projects on schedule and aligned with IGO's quality and productivity standards.": "IGO Group के एग्री विभाग में क्षेत्र प्रबंधक, जो अपने सौंपे गए क्षेत्र में दैनिक फ़ार्म संचालन और फ़ील्ड क्रियान्वयन की देखरेख करते हैं। स्थानीय फ़ील्ड टीमों और किसानों के साथ समन्वय कर एग्री परियोजनाओं को समय पर और IGO के गुणवत्ता व उत्पादकता मानकों के अनुरूप रखते हैं।",
  "Area Manager for the Agri department at IGO Group, responsible for coordinating field operations and agri project execution across his assigned region. Supervises local teams and tracks farm-level progress to support IGO's broader agri operations goals.": "IGO Group के एग्री विभाग में क्षेत्र प्रबंधक, जो अपने सौंपे गए क्षेत्र में फ़ील्ड संचालन और एग्री परियोजना क्रियान्वयन का समन्वय करते हैं। स्थानीय टीमों की निगरानी और फ़ार्म-स्तर की प्रगति पर नज़र रखकर IGO के व्यापक एग्री संचालन लक्ष्यों में सहयोग करते हैं।",
  "Area Manager for the Agri department at IGO Group, responsible for regional farm operations across his assigned area — coordinating field teams, monitoring crop progress, and ensuring agri project execution stays aligned with IGO's operational standards and timelines.": "IGO Group के एग्री विभाग में क्षेत्र प्रबंधक, जो अपने सौंपे गए क्षेत्र में क्षेत्रीय फ़ार्म संचालन के लिए ज़िम्मेदार हैं — फ़ील्ड टीमों का समन्वय, फ़सल प्रगति की निगरानी और एग्री परियोजना क्रियान्वयन को IGO के परिचालन मानकों व समय-सीमा के अनुरूप रखना।",
