  "Contractors have begun harvesting the North-East sector of Mysore Estate.": "ठेकेदारों ने मैसूर एस्टेट के उत्तर-पूर्वी हिस्से में कटाई शुरू कर दी है।",
  "Controlled growing": "नियंत्रित खेती",
  "Controlled-environment structures for high-yield crops.": "अधिक उपज वाली फ़सलों के लिए नियंत्रित-वातावरण संरचनाएँ।",
  "Conversation": "बातचीत",
  "Converted": "परिवर्तित",
  "Core Manager in IGO Group's Marketing department, responsible for the day-to-day execution of campaigns, creatives, and promotional activities across brands. Translates marketing strategy into tangible content, social media posts, event promotions, and performance reports — ensuring every brand campaign goes live on schedule and reaches the right audience with maximum impact.": "IGO Group के मार्केटिंग विभाग में कोर प्रबंधक, जो सभी ब्रांड के कैंपेन, क्रिएटिव और प्रचार गतिविधियों के दैनिक क्रियान्वयन के लिए ज़िम्मेदार हैं। मार्केटिंग रणनीति को ठोस कंटेंट, सोशल मीडिया पोस्ट, इवेंट प्रमोशन और प्रदर्शन रिपोर्ट में बदलते हैं — ताकि हर ब्रांड कैंपेन समय पर शुरू हो और सही दर्शकों तक अधिकतम प्रभाव के साथ पहुँचे।",
  "Core Manager in the Civil department at IGO Group, overseeing civil construction, site infrastructure, and building works across IGO's project sites. Manages civil project execution from planning through completion — coordinating contractors, monitoring construction quality, and ensuring civil works meet IGO's engineering and safety standards.": "IGO Group के सिविल विभाग में कोर प्रबंधक, जो IGO के परियोजना स्थलों पर सिविल निर्माण, साइट बुनियादी ढाँचे और भवन कार्यों की देखरेख करते हैं। योजना से पूर्णता तक सिविल परियोजना क्रियान्वयन का प्रबंधन, ठेकेदारों का समन्वय, निर्माण गुणवत्ता की निगरानी और IGO के इंजीनियरिंग व सुरक्षा मानकों का पालन सुनिश्चित करते हैं।",
  "Core Manager in the Farmers Factory unit at IGO Group, supporting the fresh-produce supply chain from farm-level procurement through collection hub operations and last-mile delivery. Manages the day-to-day procurement pipeline, hub operations, and logistics coordination that ensures fresh produce moves efficiently and reliably from partner farmers to IGO's distribution and retail network.": "IGO Group की Farmers Factory इकाई में कोर प्रबंधक, जो खेत-स्तर की खरीद से लेकर कलेक्शन हब संचालन और लास्ट-माइल डिलीवरी तक ताज़ा उपज की सप्लाई चेन में सहयोग करते हैं। दैनिक खरीद पाइपलाइन, हब संचालन और लॉजिस्टिक्स समन्वय का प्रबंधन करते हैं, ताकि साझेदार किसानों से IGO के वितरण व रिटेल नेटवर्क तक ताज़ा उपज कुशलता और भरोसे से पहुँचे।",
  "Core Manager in the Site Visit team at IGO Group, coordinating on-ground site visits, inspections, and field verification across IGO's agri estates and project locations. Ensures every site visit is documented accurately and findings are reported back to the relevant department for follow-up action.": "IGO Group की साइट विज़िट टीम में कोर प्रबंधक, जो IGO के एग्री एस्टेट और परियोजना स्थानों पर ज़मीनी साइट विज़िट, निरीक्षण और फ़ील्ड सत्यापन का समन्वय करते हैं। हर साइट विज़िट का सटीक दस्तावेज़ीकरण और निष्कर्षों की संबंधित विभाग को आगे की कार्रवाई हेतु रिपोर्टिंग सुनिश्चित करते हैं।",
