  "Dashboard": "डैशबोर्ड",
  "Data Analytics & Legal — Core Manager": "डेटा एनालिटिक्स और लीगल — कोर प्रबंधक",
  "Data System Management: Managing group-wide data systems and ensuring data integrity.": "डेटा सिस्टम प्रबंधन: समूह-व्यापी डेटा सिस्टम का प्रबंधन और डेटा की शुद्धता सुनिश्चित करना।",
  "Data Team Core Manager in the Data Analytics & Legal department at IGO Group, responsible for managing group-wide data systems, MIS analytics reporting, and legal documentation support. Maintains the data infrastructure that drives informed decision-making across all departments, while supporting the legal team with documentation management, compliance records, and accurate data provisioning for audits and regulatory requirements.": "IGO Group के डेटा एनालिटिक्स और लीगल विभाग में डेटा टीम कोर प्रबंधक, जो समूह-व्यापी डेटा सिस्टम, MIS एनालिटिक्स रिपोर्टिंग और कानूनी दस्तावेज़ीकरण सहयोग के लिए ज़िम्मेदार हैं। सभी विभागों में सूचित निर्णय लेने वाला डेटा ढाँचा बनाए रखते हैं और दस्तावेज़ प्रबंधन, अनुपालन रिकॉर्ड तथा ऑडिट व नियामकीय ज़रूरतों के लिए सटीक डेटा उपलब्ध कराकर लीगल टीम का सहयोग करते हैं।",
  "Data-driven crop projections and yield analysis for better returns.": "बेहतर रिटर्न के लिए डेटा-आधारित फ़सल अनुमान और उपज विश्लेषण।",
  "Date": "तारीख",
  "Deal Closure: Negotiating and closing deals.": "डील क्लोज़र: डील पर बातचीत करना और उन्हें पूरा करना।",
  "Dedicated agronomy and legal support throughout your journey.": "आपकी पूरी यात्रा में समर्पित कृषि और कानूनी सहयोग।",
  "Deep dives into Bio-CNG integration, state-wise land laws, and sustainable farming models.": "Bio-CNG एकीकरण, राज्यवार भूमि कानूनों और टिकाऊ खेती मॉडलों पर गहन जानकारी।",
  "Depends on acreage, crop, irrigation availability, labour, and input intensity.": "यह क्षेत्रफल, फसल, सिंचाई की उपलब्धता, मजदूर और इनपुट की मात्रा पर निर्भर करता है।",
  "Depends on crop density, irrigation, fencing, sapling variety, and soil condition.": "यह फसल घनत्व, सिंचाई, बाड़ेबंदी, पौधों की किस्म और मिट्टी की स्थिति पर निर्भर करता है।",
  "Describe the topography, access roads, and general condition...": "भू-आकृति, पहुँच मार्ग और सामान्य स्थिति का वर्णन करें...",
  "Detailed Description": "विस्तृत विवरण",
  "Detailed Nitrogen, Phosphorus, and Potassium profiling.": "नाइट्रोजन, फॉस्फोरस और पोटैशियम की विस्तृत प्रोफ़ाइलिंग।",
  "Detailed soil audit data available on request.": "विस्तृत मिट्टी ऑडिट डेटा अनुरोध पर उपलब्ध है।",
