  "Gain valuable insights, expert advice and practical guides to make smarter decisions in agricultural land investment.": "कृषि भूमि निवेश में बेहतर फ़ैसले लेने के लिए उपयोगी जानकारी, विशेषज्ञ सलाह और व्यावहारिक गाइड पाएँ।",
  "General Management Officer (GMO) in the Engineering department at IGO Group, overseeing engineering projects, site execution, and technical operations across IGO's construction and infrastructure verticals. Manages the full project lifecycle — from planning and material procurement through on-site supervision, quality control, and final handover — ensuring every project meets IGO's technical standards, safety requirements, and delivery timelines.": "IGO Group के इंजीनियरिंग विभाग में जनरल मैनेजमेंट ऑफ़िसर (GMO), जो IGO के निर्माण और बुनियादी ढाँचा वर्टिकल में इंजीनियरिंग परियोजनाओं, साइट क्रियान्वयन और तकनीकी संचालन की देखरेख करते हैं। योजना और सामग्री खरीद से लेकर साइट पर्यवेक्षण, गुणवत्ता नियंत्रण और अंतिम हस्तांतरण तक पूरे परियोजना जीवनचक्र का प्रबंधन करते हैं, ताकि हर परियोजना IGO के तकनीकी मानकों, सुरक्षा आवश्यकताओं और डिलीवरी समय-सीमा को पूरा करे।",
  "General Manager on the Management Operations Team and the operational backbone of IGO Group's day-to-day management. Acts as the primary bridge between department heads and the CEO office, ensuring daily operations reviews, escalation resolution, and cross-functional performance discipline are maintained consistently across all 18 departments. Plays a pivotal role in translating CEO-level directives into on-ground execution.": "मैनेजमेंट ऑपरेशंस टीम में जनरल मैनेजर और IGO Group के दैनिक प्रबंधन की परिचालन रीढ़। विभाग प्रमुखों और CEO कार्यालय के बीच मुख्य कड़ी के रूप में, सभी 18 विभागों में दैनिक संचालन समीक्षा, एस्केलेशन समाधान और अंतर-कार्यात्मक प्रदर्शन अनुशासन को लगातार बनाए रखते हैं। CEO-स्तर के निर्देशों को ज़मीनी क्रियान्वयन में बदलने में अहम भूमिका निभाते हैं।",
  "General Manager — Management Ops & BD": "जनरल मैनेजर — मैनेजमेंट ऑपरेशंस और BD",
