  "Get continued assistance based on your project requirements, helping you move forward with greater confidence as your agricultural venture grows.": "अपनी परियोजना की ज़रूरतों के अनुसार निरंतर सहायता पाएँ, ताकि आपका कृषि उद्यम बढ़ने पर आप अधिक भरोसे से आगे बढ़ सकें।",
  "Get guidance from agricultural experts and industry professionals.": "कृषि विशेषज्ञों और उद्योग पेशेवरों से मार्गदर्शन लें।",
