  "Guided by a strong sense of purpose, we are committed to building a sustainable tomorrow through innovation, responsibility and people.": "मजबूत उद्देश्य से प्रेरित होकर, हम नवाचार, जिम्मेदारी और लोगों के माध्यम से एक टिकाऊ कल बनाने के लिए प्रतिबद्ध हैं।",
