  "Harvest Scheduling: Scheduling harvest operations and logistics.": "कटाई शेड्यूलिंग: कटाई संचालन और लॉजिस्टिक्स का शेड्यूल बनाना।",
  "Harvest and grading workflow": "कटाई और ग्रेडिंग प्रक्रिया",
