  "Hello IGO, I am interested in an Agri Estate.": "नमस्ते IGO, मुझे एग्री एस्टेट में रुचि है।",
  "Hello! I can help you buy or sell Agri Estates. Ask about land categories, site visit, legal checks, posting a property, or buyer requirements.": "नमस्ते! मैं एग्री एस्टेट खरीदने या बेचने में मदद कर सकता हूँ। जमीन की श्रेणियों, साइट विज़िट, कानूनी जाँच, प्रॉपर्टी पोस्ट करने या खरीदार की ज़रूरतों के बारे में पूछें।",
  "Hello! I can help you search Agri Estates, understand buying requirements, prepare a seller listing, review land details, or ask what makes an agricultural estate attractive to serious buyers.": "नमस्ते! मैं एग्री एस्टेट खोजने, खरीदारी की आवश्यकताएँ समझने, विक्रेता लिस्टिंग तैयार करने, जमीन का विवरण जाँचने, या यह जानने में मदद कर सकता हूँ कि कृषि एस्टेट गंभीर खरीदारों को क्यों आकर्षित करता है।",
  "Hello! 👋 I'm IGO's virtual assistant. How can I help you today?\\n\\nYou can ask about:\\n- Estate types & pricing\\n- Investment returns\\n- Site visits\\n- Legal process": "नमस्ते! 👋 मैं IGO का वर्चुअल असिस्टेंट हूँ। आज मैं आपकी कैसे मदद कर सकता हूँ?\\n\\nआप इनके बारे में पूछ सकते हैं:\\n- एस्टेट के प्रकार और कीमत\\n- निवेश पर रिटर्न\\n- साइट विज़िट\\n- कानूनी प्रक्रिया",
  "Her Leadership Impact — From Learning to Livelihood: Learn (acquire knowledge) → Practice (develop hands-on skills) → Certify (validate capabilities) → Get Placed (access career opportunities) → Build (create a career or agri-business).": "उनका नेतृत्व प्रभाव — सीखने से आजीविका तक: सीखें (ज्ञान प्राप्त करें) → अभ्यास (व्यावहारिक कौशल विकसित करें) → प्रमाणित हों (क्षमताओं को प्रमाणित करें) → नौकरी पाएँ (करियर के अवसर पाएँ) → निर्माण करें (करियर या कृषि-व्यवसाय बनाएँ)।",
  "Her Vision: 'To build IGO Academy into a leading platform for practical, technology-driven and career-oriented agricultural education — empowering every learner to become job-ready, industry-ready or business-ready.'": "उनका विज़न: 'IGO Academy को व्यावहारिक, तकनीक-आधारित और करियर-उन्मुख कृषि शिक्षा का अग्रणी मंच बनाना — हर शिक्षार्थी को नौकरी, उद्योग या व्यवसाय के लिए तैयार करना।'",
  "Herbal": "जड़ी-बूटी",
  "Herbs": "जड़ी-बूटियाँ",
  "Herd-cycle based": "झुंड चक्र आधारित",
  "Here is an overview of your agri-investment interests.": "यह आपकी कृषि-निवेश रुचियों का अवलोकन है।",
  "Hide Preview": "पूर्वावलोकन छिपाएँ",
  "Hide Risk Matrix": "जोखिम तालिका छिपाएँ",
