  "Hub Operations: Managing day-to-day collection hub operations.": "हब संचालन: कलेक्शन हब के दैनिक संचालन का प्रबंधन।",
  "Human Resources Manager at IGO Group, supporting the full employee lifecycle across the organization — from recruitment and onboarding through attendance management, payroll coordination, and employee engagement. Works alongside the HR team to maintain disciplined, compliant, and engaged workforce practices across IGO Group's departments and brands.": "IGO Group में ह्यूमन रिसोर्स मैनेजर, जो पूरे संगठन में कर्मचारी जीवनचक्र को सहयोग देते हैं — भर्ती और ऑनबोर्डिंग से लेकर उपस्थिति प्रबंधन, पेरोल समन्वय और कर्मचारी जुड़ाव तक। HR टीम के साथ मिलकर IGO Group के विभागों और ब्रांडों में अनुशासित, नियम-अनुरूप और सक्रिय कार्यबल व्यवस्था बनाए रखते हैं।",
  "Humidity control": "नमी नियंत्रण",
  "Humidity setup": "नमी सेटअप",
  "Hydroponic": "हाइड्रोपोनिक",
