  "Hydroponic system design": "हाइड्रोपोनिक सिस्टम डिज़ाइन",
  "Hydroponic, vertical, and microgreens-ready estates are usually compact spaces, rooftops, clean rooms, or urban parcels. Buyers should verify water quality, power backup, hygiene readiness, and local demand.": "हाइड्रोपोनिक, वर्टिकल और माइक्रोग्रीन्स-तैयार एस्टेट आमतौर पर छोटी जगहें, छतें, क्लीन रूम या शहरी प्लॉट होते हैं। खरीदारों को पानी की गुणवत्ता, पावर बैकअप, स्वच्छता की तैयारी और स्थानीय मांग की जाँच करनी चाहिए।",
  "Hygiene and packing area": "स्वच्छता और पैकिंग क्षेत्र",
  "Hygiene discipline": "स्वच्छता अनुशासन",
  "I agree to the": "मैं सहमत हूँ",
  "I am a...": "मैं एक... हूँ",
  "I can help compare estates. Which types are you considering? Eg: Polyhouse vs Hydroponic vs Open Cultivation?": "मैं एस्टेट की तुलना में मदद कर सकता हूँ। आप कौन से प्रकार देख रहे हैं? जैसे: पॉलीहाउस बनाम हाइड्रोपोनिक बनाम खुली खेती?",
  "I have prepared a draft summary covering the requested terms, including ownership or lease structure, soil maintenance, water rights, farm access, and legal review requirements. The draft is ready for your review.": "मैंने स्वामित्व या पट्टा संरचना, मिट्टी रखरखाव, जल अधिकार, खेत तक पहुँच और कानूनी समीक्षा आवश्यकताओं सहित अनुरोधित शर्तों का मसौदा सारांश तैयार किया है। मसौदा आपकी समीक्षा के लिए तैयार है।",
  "I own agricultural land and want to list it": "मेरे पास कृषि भूमि है और मैं उसे सूचीबद्ध करना चाहता/चाहती हूँ",
  "I want to buy and invest in agricultural estates": "मैं कृषि एस्टेट खरीदकर निवेश करना चाहता/चाहती हूँ",
  "I want to buy land": "मैं जमीन खरीदना चाहता हूँ",
  "I want to sell land": "मैं जमीन बेचना चाहता हूँ",
  "I'll connect you with our estate advisor for detailed information.": "विस्तृत जानकारी के लिए मैं आपको हमारे एस्टेट सलाहकार से जोड़ता हूँ।",
  "IGO Academy": "IGO अकादमी",
  "IGO Agri Estate": "IGO एग्री एस्टेट",
  "IGO Agri Estate helps landowners unlock the value of their land and supports customers in building farm projects. We bridge the gap between land and opportunity, creating sustainable agri-communities for a better tomorrow.": "IGO Agri Estate भूमि मालिकों को उनकी जमीन का मूल्य पाने में मदद करता है और ग्राहकों को फार्म परियोजनाएँ बनाने में सहयोग देता है। हम जमीन और अवसर के बीच की दूरी पाटते हैं और बेहतर कल के लिए टिकाऊ कृषि समुदाय बनाते हैं।",
  "IGO Agri Estate is dedicated to creating value from land by connecting landowners with the right buyers and helping customers develop meaningful, sustainable agri-projects.": "IGO Agri Estate भूमि मालिकों को सही खरीदारों से जोड़कर और ग्राहकों को सार्थक, टिकाऊ कृषि परियोजनाएँ विकसित करने में मदद करके जमीन से मूल्य बनाने के लिए समर्पित है।",
  "IGO Agri Estates expert team — agricultural land investment specialists reviewing project information on a tablet in a green farm": "IGO Agri Estates विशेषज्ञ टीम — हरे-भरे फार्म में टैबलेट पर परियोजना जानकारी की समीक्षा करते कृषि भूमि निवेश विशेषज्ञ",
  "IGO Agri Estates helps you buy, sell and invest in verified agricultural land across India, with legal checks and scientific farm planning.": "IGO Agri Estates पूरे भारत में सत्यापित कृषि भूमि खरीदने, बेचने और निवेश करने में मदद करता है, कानूनी जाँच और वैज्ञानिक फार्म योजना के साथ।",
  "IGO Agri Estates home": "IGO Agri Estates होम",
  "IGO Agri Estates is the land arm of IGO Group of Companies, buying and selling agricultural land directly.": "IGO Agri Estates, IGO Group of Companies की भूमि शाखा है, जो कृषि भूमि सीधे खरीदती और बेचती है।",
  "IGO Agri Mart": "IGO एग्री मार्ट",
  "IGO Agri Estates. Land, with the project already planned. Each project pairs verified land with an IGO Agri Estate model: setup, crop plan and guidance from site visit to harvest. Right Land, Smart Planning, Complete Setup, Guidance and Support.": "IGO Agri Estates. जमीन, परियोजना पहले से योजनाबद्ध। हर परियोजना सत्यापित जमीन को IGO Agri Estate मॉडल से जोड़ती है: सेटअप, फसल योजना और साइट विज़िट से कटाई तक मार्गदर्शन। सही जमीन, स्मार्ट योजना, पूरा सेटअप, मार्गदर्शन और सहयोग।",
  "IGO Agri Estate doesn't just sell land; we build high-yielding agricultural assets. Our turnkey \"Managed Farm\" model ensures your land generates profit while you stay stress-free.": "IGO Agri Estate सिर्फ़ जमीन नहीं बेचता; हम अधिक उपज देने वाली कृषि संपत्तियाँ बनाते हैं। हमारा टर्नकी \"Managed Farm\" मॉडल सुनिश्चित करता है कि आप तनावमुक्त रहें और आपकी जमीन मुनाफ़ा कमाए।",
  "IGO Agri Estate website": "IGO Agri Estate वेबसाइट",
