  "Leadership Reporting: Reporting to the Agri Operations leadership.": "लीडरशिप रिपोर्टिंग: एग्री ऑपरेशंस नेतृत्व को रिपोर्ट करना।",
  "Leading Skills. Building Careers. Creating Farmpreneurs. Shanmathi serves as the Head of IGO Academy, leading the Academy's training strategy, academic operations, course development, learner experience, practical education, career initiatives and institutional growth. With a strong focus on practical agricultural education, technology-driven farming and career-oriented skill development, she works towards transforming IGO Academy into a future-ready learning ecosystem that connects knowledge, practical skills, employment and entrepreneurship.": "कौशल को नेतृत्व। करियर का निर्माण। फार्मप्रेन्योर तैयार करना। Shanmathi IGO Academy की प्रमुख हैं और अकादमी की प्रशिक्षण रणनीति, शैक्षणिक संचालन, पाठ्यक्रम विकास, शिक्षार्थी अनुभव, व्यावहारिक शिक्षा, करियर पहलों और संस्थागत विकास का नेतृत्व करती हैं। व्यावहारिक कृषि शिक्षा, तकनीक-आधारित खेती और करियर-उन्मुख कौशल विकास पर मजबूत ध्यान के साथ, वे IGO Academy को ऐसे भविष्य-तैयार शिक्षण इकोसिस्टम में बदल रही हैं जो ज्ञान, व्यावहारिक कौशल, रोज़गार और उद्यमिता को जोड़ता है।",
  "Leading agricultural engineering and infrastructure development for modern tech-enabled farming across India.": "पूरे भारत में आधुनिक तकनीक-आधारित खेती के लिए अग्रणी कृषि इंजीनियरिंग और बुनियादी ढाँचा विकास।",
