  "Many agricultural activities qualify for central and state schemes, such as support for drip irrigation, greenhouses and horticulture. Our advisors guide you on the schemes that may apply to your project and help with the application process. Eligibility depends on the scheme and your location.": "ड्रिप सिंचाई, ग्रीनहाउस और बागवानी के लिए सहायता जैसी कई कृषि गतिविधियाँ केंद्र और राज्य की योजनाओं के लिए पात्र होती हैं। हमारे सलाहकार आपकी परियोजना पर लागू हो सकने वाली योजनाओं पर मार्गदर्शन करते हैं और आवेदन प्रक्रिया में मदद करते हैं। पात्रता योजना और आपके स्थान पर निर्भर करती है।",
