  "Senior Management Officer (SMO) at IGO Cocopeat Factory, overseeing production operations, quality control, and day-to-day plant management for IGO's cocopeat manufacturing unit.": "IGO कोकोपीट फैक्ट्री के सीनियर मैनेजमेंट ऑफिसर (SMO), जो IGO की कोकोपीट निर्माण इकाई के उत्पादन संचालन, गुणवत्ता नियंत्रण और दैनिक प्लांट प्रबंधन की देखरेख करते हैं।",
  "Senior Management Officer (SMO) in Agri Operations at IGO Group, coordinating agri project execution, field teams, and harvest operations across assigned farm projects. Works through full farming cycles — sowing, crop maintenance, and harvest — managing field team performance, enforcing quality standards, and driving timely produce delivery to IGO's supply chain and off-take partners.": "IGO Group के एग्री ऑपरेशंस में सीनियर मैनेजमेंट ऑफिसर (SMO), जो आवंटित फार्म परियोजनाओं में कृषि परियोजना क्रियान्वयन, फील्ड टीमों और कटाई संचालन का समन्वय करते हैं। बुवाई, फसल रखरखाव और कटाई के पूरे कृषि चक्र में काम करते हुए फील्ड टीम के प्रदर्शन का प्रबंधन, गुणवत्ता मानकों का पालन और IGO की सप्लाई चेन व ऑफ-टेक साझेदारों तक समय पर उपज पहुँचाना सुनिश्चित करते हैं।",
  "Senior Management Officer (SMO) in Agri Operations at IGO Group, responsible for managing field operations, crop planning, and farm execution across assigned IGO agri projects. Supervises on-ground farm teams through every phase of the farming cycle — from soil preparation and agronomic input planning through crop maintenance and yield harvesting — ensuring operations stay on schedule, on quality, and on budget season after season.": "IGO Group के एग्री ऑपरेशंस में सीनियर मैनेजमेंट ऑफिसर (SMO), जो आवंटित IGO कृषि परियोजनाओं में फील्ड संचालन, फसल योजना और फार्म क्रियान्वयन का प्रबंधन करते हैं। मिट्टी की तैयारी और कृषि इनपुट योजना से लेकर फसल रखरखाव और उपज कटाई तक, खेती के हर चरण में जमीनी फार्म टीमों की देखरेख करते हैं और सुनिश्चित करते हैं कि हर मौसम में काम समय पर, गुणवत्ता के साथ और बजट में रहे।",
  "Senior Management Officer (SMO) supporting Farmers Factory field business development at IGO Group, coordinating on-ground farmer engagement and business growth initiatives for the Farmers Factory vertical.": "IGO Group में Farmers Factory के फील्ड बिज़नेस डेवलपमेंट को सहयोग देने वाले सीनियर मैनेजमेंट ऑफिसर (SMO), जो Farmers Factory वर्टिकल के लिए जमीनी स्तर पर किसान जुड़ाव और व्यवसाय वृद्धि पहलों का समन्वय करते हैं।",
  "Senior Management Officer (SMO) supporting Legal and IGO Hostel operations at IGO Group, coordinating compliance documentation and hostel facility management.": "IGO Group में कानून और IGO हॉस्टल संचालन को सहयोग देने वाले सीनियर मैनेजमेंट ऑफिसर (SMO), जो अनुपालन दस्तावेज़ीकरण और हॉस्टल सुविधा प्रबंधन का समन्वय करते हैं।",
