  "Visionary leader who founded IGO Group in 2016 with a mission to build a world-class sustainable farming conglomerate. Drives group strategy, investor relations, and long-term vision across all 27 brands and 18 departments — transforming Indian farming through innovation, investment, and enterprise.": "दूरदर्शी नेता जिन्होंने 2016 में IGO Group की स्थापना की, विश्वस्तरीय टिकाऊ कृषि समूह बनाने के मिशन के साथ। सभी 27 ब्रांडों और 18 विभागों में समूह रणनीति, निवेशक संबंध और दीर्घकालिक विज़न का नेतृत्व करते हैं — नवाचार, निवेश और उद्यम के माध्यम से भारतीय खेती को बदल रहे हैं।",
  "Visit Scheduling: Scheduling and coordinating site visits.": "विज़िट शेड्यूलिंग: साइट विज़िट का शेड्यूल और समन्वय।",
  "Visit Website": "वेबसाइट देखें",
  "Visit your preferred property, assess the land, and understand its location, accessibility, soil conditions, water availability, and development potential.": "अपनी पसंदीदा संपत्ति देखें, जमीन का आकलन करें और उसकी लोकेशन, पहुँच, मिट्टी की स्थिति, पानी की उपलब्धता और विकास क्षमता को समझें।",
