  "Yes. After handover we continue to support you with farm management guidance, crop planning, maintenance and troubleshooting, so your farm keeps performing season after season.": "हाँ। हैंडओवर के बाद भी हम फार्म प्रबंधन मार्गदर्शन, फसल योजना, रखरखाव और समस्या-समाधान में सहयोग जारी रखते हैं, ताकि आपका फार्म सीज़न दर सीज़न अच्छा प्रदर्शन करता रहे।",
  "Yes. Every property goes through legal verification of title, encumbrance and land-use status before it is listed, and we share the documentation with you openly.": "हाँ। हर संपत्ति की लिस्टिंग से पहले स्वामित्व, भार (एन्कम्ब्रेंस) और भूमि-उपयोग स्थिति की कानूनी जाँच होती है, और हम दस्तावेज़ आपके साथ खुलकर साझा करते हैं।",
  "Yes. Our team supports the full journey from land preparation, soil testing and levelling to irrigation, fencing, greenhouse setup, plantation, and farm sheds, storage and roads, all planned around your goals and budget.": "हाँ। हमारी टीम पूरी यात्रा में सहयोग देती है: भूमि तैयारी, मिट्टी परीक्षण और समतलीकरण से लेकर सिंचाई, बाड़बंदी, ग्रीनहाउस सेटअप, बागान, फार्म शेड, भंडारण और सड़कों तक, सब कुछ आपके लक्ष्यों और बजट के अनुसार नियोजित।",
