  "How can we assist you today?": "आज हम आपकी किस प्रकार सहायता कर सकते हैं?",
  "Tell us about road access, soil condition, fencing, crop use, title preference, or buying timeline...": "सड़क पहुँच, मिट्टी की स्थिति, बाड़बंदी, फसल उपयोग, स्वामित्व प्राथमिकता या खरीद की समय-सीमा के बारे में हमें बताएँ...",
  "Dr. John Yesudhas, Founder and CEO of IGO Group of Companies": "डॉ. जॉन येसुदास, आई.जी.ओ समूह की कंपनियों के संस्थापक एवं मुख्य कार्यकारी अधिकारी",
  "IGO Agri Estates | Buy & Sell Managed Agricultural Land in India": "आई.जी.ओ एग्री एस्टेट्स | भारत में प्रबंधित कृषि भूमि खरीदें और बेचें",
  "IGO Agri Estates — India's premium platform to buy, sell, and invest in verified managed agricultural land. Teak plantations, mango orchards, polyhouse farms, and horticulture estates across Tamil Nadu, Karnataka, Maharashtra, Andhra Pradesh & Telangana. Clear titles. Farm-as-a-service support.": "आई.जी.ओ एग्री एस्टेट्स — सत्यापित प्रबंधित कृषि भूमि को खरीदने, बेचने और उसमें निवेश करने का भारत का प्रीमियम मंच। तमिलनाडु, कर्नाटक, महाराष्ट्र, आंध्र प्रदेश और तेलंगाना में सागौन के बागान, आम के बाग, पॉलीहाउस फार्म और बागवानी एस्टेट। स्पष्ट स्वामित्व। फार्म-एज़-ए-सर्विस सहायता।",
  "Transferring you to a human agent... Please call +91 8376883780 or email info@igoagritechfarms.com": "आपको एक मानव एजेंट से जोड़ा जा रहा है... कृपया +91 8376883780 पर कॉल करें या info@igoagritechfarms.com पर ईमेल करें",
