  "Grow With a Collaborative Team": "सहयोगी टीम के साथ आगे बढ़ें",
  "Work alongside professionals in sales, operations, engineering, marketing and customer relations.": "बिक्री, संचालन, इंजीनियरिंग, मार्केटिंग और ग्राहक संबंधों के पेशेवरों के साथ काम करें।",
  "Innovation in Agriculture": "कृषि में नवाचार",
  "Explore modern approaches to agricultural land assessment, farm infrastructure and sustainable development.": "कृषि भूमि आकलन, फार्म अवसंरचना और टिकाऊ विकास के आधुनिक तरीकों को जानें।",
  "Find your place": "अपनी जगह खोजें",
  "Explore Career Opportunities": "करियर अवसर देखें",
  "Whether you are passionate about agriculture, land development, business or technology, discover opportunities to contribute your skills and grow with us.": "चाहे आपको कृषि, भूमि विकास, व्यवसाय या तकनीक में रुचि हो, अपने कौशल का योगदान देने और हमारे साथ आगे बढ़ने के अवसर खोजें।",
