  "Sales & Business Development": "बिक्री और व्यवसाय विकास",
  "Customer consultations, property presentations, lead management and investment enquiries.": "ग्राहक परामर्श, प्रॉपर्टी प्रस्तुतियाँ, लीड प्रबंधन और निवेश पूछताछ।",
  "Customer Experience & Administration": "ग्राहक अनुभव और प्रशासन",
