  "Sales Executive, Business Development Executive, Relationship Manager": "सेल्स एक्ज़ीक्यूटिव, बिज़नेस डेवलपमेंट एक्ज़ीक्यूटिव, रिलेशनशिप मैनेजर",
  "Customer Relationship Executive, Site Visit Coordinator, Operations Executive": "कस्टमर रिलेशनशिप एक्ज़ीक्यूटिव, साइट विज़िट समन्वयक, ऑपरेशंस एक्ज़ीक्यूटिव",
  "Note: These are career categories, not confirmed vacancies. Specific openings are shown only when verified by IGO Agri Estate.": "नोट: ये करियर श्रेणियाँ हैं, पुष्ट रिक्तियाँ नहीं। विशिष्ट पद तभी दिखाए जाते हैं जब IGO एग्री एस्टेट उन्हें सत्यापित कर ले।",
  "Your future starts here": "आपका भविष्य यहाँ से शुरू होता है",
  "More Than a Job. A Path to Growth.": "सिर्फ़ नौकरी नहीं। विकास का रास्ता।",
