  "Career Progression": "करियर प्रगति",
  "Build your experience and develop the skills needed to take on greater responsibilities.": "अपना अनुभव बढ़ाएँ और बड़ी ज़िम्मेदारियाँ संभालने के लिए ज़रूरी कौशल विकसित करें।",
