  "Real-World Exposure": "वास्तविक दुनिया का अनुभव",
  "Gain hands-on experience through site visits, planning activities and project work.": "साइट विज़िट, योजना गतिविधियों और परियोजना कार्य के ज़रिए प्रत्यक्ष अनुभव पाएँ।",
  "Take the next step": "अगला कदम उठाएँ",
  "Ready to Grow With Us?": "हमारे साथ आगे बढ़ने के लिए तैयार हैं?",
  "We would love to hear from you. Tell us about your experience, interests and the kind of impact you want to make.": "हम आपसे सुनना चाहेंगे। हमें अपने अनुभव, रुचियों और उस प्रभाव के बारे में बताएँ जो आप बनाना चाहते हैं।",
