  "Thank you for applying to IGO Agri Estate. Our team will review your details and get in touch if there is a suitable opportunity.": "IGO एग्री एस्टेट में आवेदन करने के लिए धन्यवाद। हमारी टीम आपके विवरण की समीक्षा करेगी और उपयुक्त अवसर होने पर संपर्क करेगी।",
