  "Your details are used only to review your application. Resumes are stored privately.": "आपके विवरण का उपयोग केवल आपके आवेदन की समीक्षा के लिए होता है। रिज़्यूमे निजी रूप से संग्रहीत किए जाते हैं।",
  "Please enter your full name.": "कृपया अपना पूरा नाम दर्ज करें।",
