  "Please tell us which position you are applying for.": "कृपया बताएँ कि आप किस पद के लिए आवेदन कर रहे हैं।",
  "Please tell us a little more about yourself (at least 20 characters).": "कृपया अपने बारे में थोड़ा और बताएँ (कम से कम 20 अक्षर)।",
