  "This file is empty. Please choose another file.": "यह फ़ाइल खाली है। कृपया दूसरी फ़ाइल चुनें।",
  "The file is larger than 5 MB. Please upload a smaller file.": "फ़ाइल 5 MB से बड़ी है। कृपया छोटी फ़ाइल अपलोड करें।",
  "Applications are not available right now. Please try again later or contact us directly.": "आवेदन अभी उपलब्ध नहीं हैं। कृपया बाद में प्रयास करें या सीधे हमसे संपर्क करें।",
  "We could not upload your resume. Please check the file (PDF, DOC or DOCX, up to 5 MB) and try again.": "हम आपका रिज़्यूमे अपलोड नहीं कर सके। कृपया फ़ाइल (PDF, DOC या DOCX, 5 MB तक) जाँचें और फिर प्रयास करें।",
  "We could not save your application. Nothing was submitted, so please try again in a moment.": "हम आपका आवेदन सहेज नहीं सके। कुछ भी जमा नहीं हुआ, कृपया थोड़ी देर बाद फिर प्रयास करें।",
  "Life at IGO Agri Estate": "IGO एग्री एस्टेट में जीवन",
  "A Team Driven by Land, Growth and Possibility": "भूमि, विकास और संभावनाओं से प्रेरित टीम",
  "We believe that meaningful progress comes from people who share ideas, work together and take pride in what they build. At IGO Agri Estate, our goal is to bring together passionate individuals who want to contribute to responsible land development and the future of agricultural investment.": "हमारा मानना है कि सार्थक प्रगति उन लोगों से आती है जो विचार साझा करते हैं, मिलकर काम करते हैं और अपने बनाए पर गर्व करते हैं। IGO एग्री एस्टेट में हमारा लक्ष्य ऐसे जुनूनी लोगों को साथ लाना है जो ज़िम्मेदार भूमि विकास और कृषि निवेश के भविष्य में योगदान देना चाहते हैं।",
  "Bring Your Ideas. Build Something Meaningful.": "अपने विचार लाएँ। कुछ सार्थक बनाएँ।",
  "Whether you are starting your career or bringing years of professional experience, we welcome people who are ready to learn, collaborate and make a difference.": "चाहे आप करियर शुरू कर रहे हों या वर्षों का अनुभव लेकर आए हों, हम उन लोगों का स्वागत करते हैं जो सीखने, सहयोग करने और बदलाव लाने के लिए तैयार हैं।",
  "Your next opportunity could start here.": "आपका अगला अवसर यहीं से शुरू हो सकता है।",
  "Let’s Build the Future of Agri Estate Together.": "आइए मिलकर एग्री एस्टेट का भविष्य बनाएँ।",
  "Discover a career where your skills, ideas and ambitions can help shape tomorrow’s agricultural landscape.": "ऐसा करियर खोजें जहाँ आपके कौशल, विचार और महत्वाकांक्षाएँ कल के कृषि परिदृश्य को आकार देने में मदद करें।",
  "Careers | Join IGO Agri Estate": "करियर | IGO एग्री एस्टेट से जुड़ें",
