  'Apply now': 'अभी आवेदन करें',
  "Visit": "देखें",
  "Farm Loans": "फ़ार्म लोन",
  "Explore agricultural land and farm opportunities that match your budget, preferred location, investment goals, and farming interests.": "अपने बजट, पसंदीदा स्थान, निवेश लक्ष्यों और खेती की रुचियों के अनुरूप कृषि भूमि और फ़ार्म के अवसर खोजें।",
  "Get financial assistance to purchase agricultural land and start your farming journey. We help you explore suitable loan options and guide you through the financing process based on your eligibility and project requirements.": "कृषि भूमि खरीदने और अपनी खेती की यात्रा शुरू करने के लिए वित्तीय सहायता प्राप्त करें। हम आपकी पात्रता और परियोजना की आवश्यकताओं के आधार पर उपयुक्त लोन विकल्प खोजने और वित्तपोषण प्रक्रिया में मार्गदर्शन करने में मदद करते हैं।",
  "Prime Location": "प्राइम लोकेशन",
